using EEMS.Modules.Polling.Domain;using Microsoft.EntityFrameworkCore;
namespace EEMS.Modules.Polling.Infrastructure;
public sealed class PollingDbContext(DbContextOptions<PollingDbContext> options):DbContext(options)
{
    public DbSet<PollingCenter> Centers=>Set<PollingCenter>();public DbSet<Booth> Booths=>Set<Booth>();public DbSet<ElectionCenter> ElectionCenters=>Set<ElectionCenter>();public DbSet<AgentAssignment> AgentAssignments=>Set<AgentAssignment>();public DbSet<CenterVerification> CenterVerifications=>Set<CenterVerification>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.HasDefaultSchema("polling");
        var center=modelBuilder.Entity<PollingCenter>();center.ToTable("centers");center.HasKey(x=>x.Id);center.Property(x=>x.Id).HasColumnName("center_id");center.Property(x=>x.AreaId).HasColumnName("area_id");center.Property(x=>x.Code).HasColumnName("code").HasMaxLength(50);center.Property(x=>x.Name).HasColumnName("name").HasMaxLength(250);center.Property(x=>x.Address).HasColumnName("address").HasMaxLength(500);center.Property(x=>x.CreatedAtUtc).HasColumnName("created_at");center.HasIndex(x=>new{x.AreaId,x.Code}).IsUnique();
        var booth=modelBuilder.Entity<Booth>();booth.ToTable("booths");booth.HasKey(x=>x.Id);booth.Property(x=>x.Id).HasColumnName("booth_id");booth.Property(x=>x.CenterId).HasColumnName("center_id");booth.Property(x=>x.Code).HasColumnName("code").HasMaxLength(50);booth.Property(x=>x.Name).HasColumnName("name").HasMaxLength(120);booth.Property(x=>x.IsActive).HasColumnName("is_active");booth.HasIndex(x=>new{x.CenterId,x.Code}).IsUnique();booth.HasOne<PollingCenter>().WithMany().HasForeignKey(x=>x.CenterId).OnDelete(DeleteBehavior.Restrict);
        var electionCenter=modelBuilder.Entity<ElectionCenter>();electionCenter.ToTable("election_centers");electionCenter.HasKey(x=>x.Id);electionCenter.Property(x=>x.Id).HasColumnName("election_center_id");electionCenter.Property(x=>x.TenantId).HasColumnName("tenant_id");electionCenter.Property(x=>x.ElectionId).HasColumnName("election_id");electionCenter.Property(x=>x.CenterId).HasColumnName("center_id");electionCenter.Property(x=>x.IsVerified).HasColumnName("is_verified");electionCenter.Property(x=>x.CreatedAtUtc).HasColumnName("created_at");electionCenter.HasIndex(x=>new{x.TenantId,x.ElectionId,x.CenterId}).IsUnique();electionCenter.HasIndex(x=>new{x.TenantId,x.Id}).IsUnique();electionCenter.HasOne<PollingCenter>().WithMany().HasForeignKey(x=>x.CenterId).OnDelete(DeleteBehavior.Restrict);
        var assignment=modelBuilder.Entity<AgentAssignment>();assignment.ToTable("agent_assignments");assignment.HasKey(x=>x.Id);assignment.Property(x=>x.Id).HasColumnName("agent_assignment_id");assignment.Property(x=>x.TenantId).HasColumnName("tenant_id");assignment.Property(x=>x.ElectionCenterId).HasColumnName("election_center_id");assignment.Property(x=>x.UserId).HasColumnName("user_id");assignment.Property(x=>x.StartsAtUtc).HasColumnName("starts_at");assignment.Property(x=>x.EndsAtUtc).HasColumnName("ends_at");assignment.Property(x=>x.IsActive).HasColumnName("is_active");assignment.HasIndex(x=>new{x.TenantId,x.ElectionCenterId,x.UserId,x.StartsAtUtc}).IsUnique();assignment.HasOne<ElectionCenter>().WithMany().HasForeignKey(x=>x.ElectionCenterId).OnDelete(DeleteBehavior.Cascade);
        var verification=modelBuilder.Entity<CenterVerification>();verification.ToTable("center_verifications");verification.HasKey(x=>x.Id);verification.Property(x=>x.Id).HasColumnName("center_verification_id");verification.Property(x=>x.TenantId).HasColumnName("tenant_id");verification.Property(x=>x.ElectionCenterId).HasColumnName("election_center_id");verification.Property(x=>x.VerifiedByUserId).HasColumnName("verified_by_user_id");verification.Property(x=>x.VerifiedAtUtc).HasColumnName("verified_at");verification.HasIndex(x=>new{x.TenantId,x.ElectionCenterId,x.VerifiedAtUtc});verification.HasOne<ElectionCenter>().WithMany().HasForeignKey(x=>x.ElectionCenterId).OnDelete(DeleteBehavior.Cascade);
    }
}
